**Gates before launch**

I launch the same script three times and stop if any launch fails. The first launch uses `{mode: "gates"}`. It checks that spe/evals/tasks has exactly 50 unique tickets. It runs the grader selftest: the oracle built from answers.json must score 1.0 on both label.category and label.priority, and the empty and wrong prediction files must score 0 or exit with an error. It also regrades round 3's saved runs with today's grade.py, and those numbers must match the r03 rows in spe/prediction-log.md within 0.005. The second launch uses `{mode: "dry"}`. It runs 1 trial each of B and C2 on 1 ticket, which is 2 cells, through the whole pipeline: runner, peek scan, grader, Opus judge, failure analysis, critic, and record. I read that output myself. I confirm that the scan found the transcripts, that the grader rows match the grader summary, and that the logged spend looks right. Then I commit the script as `SPE r04 evaluate (harness)` and launch `{mode: "full", capUsd: <40 minus gates and dry spend>}`. The full launch runs the inventory and selftest again before any trial, because the grader could change between launches.

**Assumptions to check before the gates launch**

The trial rules did not let me read r03-workflow.js. So these values are `args` with defaults, and they need to match r03:
- `runnerCmd` (default `python spe/evals/harness/run_config.py --config {config} --tickets {tickets} --seed {seed} --out {out}`)
- `gradeCmd` (default `python spe/evals/graders/grade.py --pred {pred} --answers spe/evals/tasks/answers.json --json`)
- `ticketsFile`
- the run file names in `files`
- the per-call cost estimates

Each launch keeps its own spend counter. That is why the full launch's `capUsd` has to subtract what the gates and dry launches spent. The cost figures are unmeasured estimates. With the defaults, the full run's base work comes to about $24, which leaves room for extra trials under the cap.

```js
export const meta = {
  name: "spe-eval-round",
  description: "SPE eval for configs B and C2 on 50 support tickets, 5 trials per cell. A code grader checks label.category and label.priority. An Opus judge scores reply tone. Paid work stops at the spend cap. The round number lives in the ROUND constant.",
  phases: ["Gates", "Trials", "Peek scan", "Grade", "Judge", "Split cells", "Failure analysis", "Completeness critic", "Record"],
};

// ---------- Round ----------
const ROUND = 4;
const pad2 = (n) => String(n).padStart(2, "0");
const R = `r${pad2(ROUND)}`;
const PREV = `r${pad2(ROUND - 1)}`;

// ---------- Settings (args override defaults) ----------
const A = typeof args === "object" && args !== null ? args : {};
const MODE = A.mode ?? "full"; // launch order: "gates", then "dry", then "full"
if (!["gates", "dry", "full"].includes(MODE)) {
  throw new Error(`args.mode must be "gates", "dry", or "full". Got ${JSON.stringify(MODE)}.`);
}
const MODEL = A.model ?? "opus";
const JUDGE_MODEL = "opus";
const CAP_USD = A.capUsd ?? 40;
const CLOSE_RESERVE_USD = A.closeReserveUsd ?? 1.5; // kept back so the run can always report
const EXPECTED_TICKETS = A.expectedTickets ?? 50;
const TRIALS = MODE === "dry" ? 1 : (A.trials ?? 5);
const DRY_TICKETS = A.dryTickets ?? 1; // 1 ticket x 2 configs = 2 cells
const MAX_EXTRA_ROUNDS = A.maxExtraRounds ?? 5; // cap on extra trials per split cell
const SPLIT_LO = A.splitLo ?? 0.3;
const SPLIT_HI = A.splitHi ?? 0.7;
const CONTROL_TOL = A.controlTolerance ?? 0.005;

const CONFIGS = A.configs ?? [
  { id: "B", desc: "12-line prompt, 6 tools" },
  { id: "C2", desc: "12-line prompt, 3 tools plus a separate check_status tool" },
];

const P = {
  tickets: A.ticketsFile ?? "spe/evals/tasks/tickets.json",
  answers: "spe/evals/tasks/answers.json",
  grader: "spe/evals/graders/grade.py",
  judge: "spe/evals/graders/judge.md",
  runs: `spe/evals/runs/${R}`,
  prevRuns: `spe/evals/runs/${PREV}`,
  gates: `spe/evals/runs/${R}/gates`,
  results: "spe/evals/results",
};
const FILES = { labels: "labels.json", replies: "replies.json", transcript: "transcript.jsonl", summary: "summary.json", ...(A.files ?? {}) };
const RUNNER_CMD = A.runnerCmd ?? "python spe/evals/harness/run_config.py --config {config} --tickets {tickets} --seed {seed} --out {out}";
const GRADE_CMD = A.gradeCmd ?? "python spe/evals/graders/grade.py --pred {pred} --answers spe/evals/tasks/answers.json --json";

// Unmeasured estimates. Runner cost is replaced by summary.json cost when the runner reports it.
const EST = {
  agent: A.estAgentUsd ?? 0.25,
  runnerPerTicket: A.estRunnerPerTicketUsd ?? 0.02,
  judgePerTicket: A.estJudgePerTicketUsd ?? 0.01,
};

// Trials must not touch these. A hit voids the trial. A hit on the answer key halts the round.
const LEAK_PATTERNS = ["answers.json"];
const PEEK_PATTERNS = ["answers.json", "spe/evals/graders", "grade.py", "judge.md", "spe/predictions", "prediction-log.md", "spe/plans", "spe/evals/results", "failures.md"];

// ---------- Small helpers ----------
const fill = (tpl, vars) => tpl.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const ratio = (a, n) => (n ? a / n : null);
const r2 = (x) => Math.round(x * 100) / 100;
const pct = (x) => (x === null || x === undefined ? "n/a" : `${(100 * x).toFixed(1)}%`);
const patternsIn = (s, pats) => pats.filter((p) => String(s).includes(p));

const state = { halted: false, haltReason: null, budgetCapHit: false };
function halt(reason) {
  if (!state.halted) {
    state.halted = true;
    state.haltReason = reason;
    log(`HALT: ${reason}`);
  }
}

const budget = { spentUsd: 0, skips: [] };
function tryReserve(usd, what, closing = false) {
  const limit = closing ? CAP_USD : CAP_USD - CLOSE_RESERVE_USD;
  if (budget.spentUsd + usd > limit) {
    budget.skips.push({ what, estUsd: r2(usd), spentUsdAtSkip: r2(budget.spentUsd) });
    log(`SKIP ${what}. It needs about $${usd.toFixed(2)}. Spend so far is $${budget.spentUsd.toFixed(2)} of $${CAP_USD}.`);
    if (!closing) {
      state.budgetCapHit = true;
      halt("spend cap reached");
    }
    return false;
  }
  budget.spentUsd += usd;
  return true;
}
function settle(estUsd, actualUsd) {
  if (Number.isFinite(actualUsd) && actualUsd >= 0) budget.spentUsd += actualUsd - estUsd;
}

async function callAgent(prompt, opts) {
  try {
    return await agent(prompt, { model: MODEL, ...opts });
  } catch (e) {
    log(`Agent ${opts.label} failed: ${e && e.message ? e.message : String(e)}`);
    return null;
  }
}

// ---------- Schemas ----------
const STR = { type: "string" };
const INT = { type: "integer" };
const NUM = { type: "number" };
const NUM_OR_NULL = { type: ["number", "null"] };
const BOOL = { type: "boolean" };
const obj = (props, required = Object.keys(props)) => ({ type: "object", properties: props, required });
const arr = (items) => ({ type: "array", items });

const INVENTORY_SCHEMA = obj({ ticketIds: arr(STR), count: INT });
const SCORE = obj({ exitCode: INT, n: INT, categoryAcc: NUM_OR_NULL, priorityAcc: NUM_OR_NULL, stderrTail: STR }, ["exitCode", "n", "categoryAcc", "priorityAcc"]);
const SELFTEST_SCHEMA = obj({ oracle: SCORE, empty: SCORE, wrong: SCORE });
const CONTROL_SCHEMA = obj({ runsRegraded: INT, rows: arr(obj({ config: STR, metric: STR, recorded: NUM_OR_NULL, regraded: NUM_OR_NULL })) });
const TRIAL_SCHEMA = obj({ exitCode: INT, ticketsProcessed: INT, runnerCostUsd: NUM_OR_NULL, commands: arr(STR), stderrTail: STR }, ["exitCode", "ticketsProcessed", "runnerCostUsd", "commands"]);
const SCAN_SCHEMA = obj({ scanned: arr(STR), missing: arr(STR), hits: arr(obj({ runId: STR, pattern: STR, line: INT, text: STR })) });
const GRADE_SCHEMA = obj(
  {
    exitCode: INT,
    tickets: arr(obj({ ticketId: STR, categoryCorrect: BOOL, priorityCorrect: BOOL })),
    summary: obj({ n: INT, categoryAcc: NUM_OR_NULL, priorityAcc: NUM_OR_NULL }),
    stderrTail: STR,
  },
  ["exitCode", "tickets", "summary"]
);
const JUDGE_SCHEMA = obj({ tickets: arr(obj({ ticketId: STR, tonePass: BOOL, score: NUM, reason: STR })) });
const ANALYSIS_SCHEMA = obj({
  failureTypes: arr(obj({ name: STR, kind: STR, existingId: { type: ["string", "null"] }, what: STR, howToSpot: STR, seenIn: arr(STR), configs: arr(STR), count: INT })),
  graderSuspects: arr(obj({ ticketId: STR, field: STR, evidence: STR })),
  notes: STR,
});
const CRITIC_SCHEMA = obj({ complete: BOOL, gaps: arr(obj({ what: STR, severity: { type: "string", enum: ["blocker", "major", "minor"] }, fix: STR })) });
const RECORD_SCHEMA = obj({ path: STR, bytes: INT });

// ---------- Gates ----------
async function gateInventory() {
  if (!tryReserve(EST.agent, "gate: ticket inventory")) return { ok: false, why: "spend cap" };
  const inv = await callAgent(
    [
      `You are checking the ticket set for SPE round ${ROUND}.`,
      `Read ${P.tickets} and nothing else. Return every ticket id in file order, and the count.`,
      `Do not open any path that contains any of these strings: ${PEEK_PATTERNS.join(", ")}.`,
      `Do not edit any file.`,
    ].join("\n"),
    { label: "gate-inventory", phase: "Gates", schema: INVENTORY_SCHEMA }
  );
  if (!inv) return { ok: false, why: "inventory agent returned nothing" };
  const ids = inv.ticketIds;
  const unique = new Set(ids).size === ids.length;
  const ok = unique && ids.length === EXPECTED_TICKETS && inv.count === ids.length;
  return { ok, ids, why: ok ? null : `got ${ids.length} ids (agent said ${inv.count}), unique=${unique}, expected ${EXPECTED_TICKETS}` };
}

async function gateSelftest() {
  if (!tryReserve(EST.agent, "gate: grader selftest")) return { ok: false, why: "spend cap" };
  const cmd = (name) => fill(GRADE_CMD, { pred: `${P.gates}/${name}.json` });
  const s = await callAgent(
    [
      `You are testing the SPE round ${ROUND} grader before any trial runs.`,
      `You may read ${P.grader}, ${P.answers}, and one existing ${FILES.labels} under ${P.prevRuns} to learn the prediction format. Do not edit ${P.grader}.`,
      `1. Create the folder ${P.gates}.`,
      `2. Oracle: write ${P.gates}/oracle.json in the prediction format. Copy label.category and label.priority from ${P.answers} for every ticket. Run: ${cmd("oracle")}`,
      `3. Empty: write ${P.gates}/empty.json as a prediction file with no tickets in it. Run: ${cmd("empty")}`,
      `4. Wrong: write ${P.gates}/wrong.json with every ticket present. Set label.category and label.priority to an allowed value that differs from the answer. Run: ${cmd("wrong")}`,
      `For each run, report the exit code, the number of tickets the grader scored (n), and categoryAcc and priorityAcc as fractions from 0 to 1, as the grader printed them.`,
      `If the grader crashes, report the exit code and the last 20 lines of stderr. Do not fix anything.`,
    ].join("\n"),
    { label: "gate-selftest", phase: "Gates", schema: SELFTEST_SCHEMA }
  );
  if (!s) return { ok: false, why: "selftest agent returned nothing" };
  const { oracle, empty, wrong } = s;
  const problems = [];
  if (!(oracle.exitCode === 0 && oracle.n === EXPECTED_TICKETS && oracle.categoryAcc === 1 && oracle.priorityAcc === 1)) {
    problems.push(`oracle did not score 1.0 on both fields: ${JSON.stringify(oracle)}`);
  }
  const emptyLoud = empty.exitCode !== 0;
  const emptyZero = empty.exitCode === 0 && empty.n === EXPECTED_TICKETS && empty.categoryAcc === 0 && empty.priorityAcc === 0;
  if (!(emptyLoud || emptyZero)) problems.push(`empty predictions neither failed nor scored 0 over ${EXPECTED_TICKETS}: ${JSON.stringify(empty)}`);
  if (!(wrong.exitCode === 0 && wrong.n === EXPECTED_TICKETS && wrong.categoryAcc === 0 && wrong.priorityAcc === 0)) {
    problems.push(`wrong predictions did not score 0: ${JSON.stringify(wrong)}`);
  }
  return { ok: problems.length === 0, result: s, why: problems.join(" | ") || null };
}

async function gateControl() {
  if (!tryReserve(EST.agent * 2, "gate: regrade control")) return { ok: false, why: "spend cap" };
  const c = await callAgent(
    [
      `You are running a control for SPE round ${ROUND}. Regrade round ${PREV} with the current grader.`,
      `1. List the run folders under ${P.prevRuns}. For each folder that has ${FILES.labels}, run: ${fill(GRADE_CMD, { pred: `<folder>/${FILES.labels}` })}`,
      `2. Pool the per-ticket results by config. Use the config named in each folder's ${FILES.summary}.`,
      `3. Read the round ${PREV} rows in spe/prediction-log.md. For each config, report the recorded Measured value and your regraded value for category accuracy and priority accuracy, as fractions from 0 to 1. Use null where a number does not exist.`,
      `Do not edit any file.`,
    ].join("\n"),
    { label: "gate-control", phase: "Gates", schema: CONTROL_SCHEMA }
  );
  if (!c) return { ok: false, why: "control agent returned nothing" };
  const comparable = c.rows.filter((x) => Number.isFinite(x.recorded) && Number.isFinite(x.regraded));
  const off = comparable.filter((x) => Math.abs(x.recorded - x.regraded) > CONTROL_TOL);
  const ok = c.runsRegraded > 0 && comparable.length > 0 && off.length === 0;
  const why = ok ? null : comparable.length === 0 ? `no comparable round ${PREV} rows` : `regrade differs from recorded: ${JSON.stringify(off)}`;
  return { ok, result: c, why };
}

// ---------- Trials ----------
let seq = 0;
let allTickets = [];
let runTickets = [];

function makeRun(cfg, tickets, trial, kind, seed) {
  seq += 1;
  const runId = `${R}-${MODE}-${String(seq).padStart(3, "0")}`; // config is not in the id, so the judge stays blind
  return { runId, config: cfg.id, configDesc: cfg.desc, trial, kind, seed, tickets, out: `${P.runs}/${runId}`, status: "planned" };
}

function trialPrompt(r, cmd) {
  return [
    `You are running one trial for SPE round ${ROUND}. Run id: ${r.runId}.`,
    `Run this one shell command from the repository root and wait for it to finish:`,
    "",
    cmd,
    "",
    `Then read ${r.out}/${FILES.summary}. Report the exit code, the number of tickets processed, and the runner cost in USD if the summary has it (otherwise null).`,
    `Rules:`,
    `- Do not open, list, search, or print any path that contains any of these strings: ${PEEK_PATTERNS.join(", ")}.`,
    `- Do not read any other file. Do not edit any file. Do not change the command or retry with other flags.`,
    `- If the command fails, report its exit code and the last 20 lines of stderr.`,
    `- List every shell command you ran, exactly as you ran it, in "commands".`,
  ].join("\n");
}

async function runTrial(r, ph) {
  if (state.halted) return { ...r, status: "skipped", why: `halted: ${state.haltReason}` };
  const est = EST.agent + EST.runnerPerTicket * r.tickets.length;
  if (!tryReserve(est, `trial ${r.runId} (${r.config} ${r.trial}, ${r.tickets.length} tickets)`)) return { ...r, status: "skipped", why: "spend cap" };
  const ticketArg = r.tickets.length === allTickets.length ? "all" : r.tickets.join(",");
  const cmd = fill(RUNNER_CMD, { config: r.config, tickets: ticketArg, seed: r.seed, out: r.out, round: ROUND });
  const res = await callAgent(trialPrompt(r, cmd), { label: `trial-${r.runId}`, phase: ph, schema: TRIAL_SCHEMA });
  if (!res) return { ...r, status: "error", why: "trial agent returned nothing" };
  if (Number.isFinite(res.runnerCostUsd)) settle(est, EST.agent + res.runnerCostUsd);

  // Code check first: did the trial agent itself touch a forbidden path?
  const peeks = res.commands.flatMap((c) => patternsIn(c, PEEK_PATTERNS).map((p) => ({ pattern: p, text: c.slice(0, 200) })));
  if (peeks.length) {
    if (peeks.some((h) => LEAK_PATTERNS.includes(h.pattern))) halt(`leaked answer key: trial agent ${r.runId} touched ${LEAK_PATTERNS.join(", ")}`);
    return { ...r, status: "void", why: "trial agent command touched a forbidden path", evidence: peeks };
  }
  if (res.exitCode !== 0) return { ...r, status: "error", why: `runner exit ${res.exitCode}`, stderrTail: res.stderrTail ?? "" };
  if (res.ticketsProcessed !== r.tickets.length) return { ...r, status: "error", why: `runner processed ${res.ticketsProcessed} of ${r.tickets.length} tickets` };
  return { ...r, status: "ok", runnerCostUsd: res.runnerCostUsd };
}

// ---------- Peek scan ----------
async function peekScan(runs, ph) {
  const ok = runs.filter((r) => r.status === "ok");
  if (!ok.length) return runs;
  if (!tryReserve(EST.agent, `peek scan of ${ok.length} runs`)) {
    return runs.map((r) => (r.status === "ok" ? { ...r, status: "void", why: "not scanned (spend cap)" } : r));
  }
  const list = ok.map((r) => `${r.runId} ${r.out}/${FILES.transcript}`).join("\n");
  const s = await callAgent(
    [
      `You are checking SPE round ${ROUND} trial transcripts for peeking. Each line below is a run id, a space, and a transcript path.`,
      list,
      `For each transcript, run grep -n -F once for each of these patterns: ${PEEK_PATTERNS.map((p) => JSON.stringify(p)).join(", ")}.`,
      `Report every match with the run id, the pattern, the line number, and the matched line cut to 200 characters. Do not decide whether a match matters. Code decides that.`,
      `Put a run id in "scanned" only if its transcript exists and you ran every pattern on it. Put a run id in "missing" if its transcript does not exist.`,
      `Do not open any file other than the listed transcripts. Do not edit any file.`,
    ].join("\n"),
    { label: `peek-scan-${ok[0].runId}`, phase: ph, schema: SCAN_SCHEMA }
  );
  const scanned = new Set(s ? s.scanned : []);
  const missing = new Set(s ? s.missing : []);
  const hitsBy = new Map();
  for (const h of s ? s.hits : []) {
    if (!hitsBy.has(h.runId)) hitsBy.set(h.runId, []);
    hitsBy.get(h.runId).push(h);
  }
  return runs.map((r) => {
    if (r.status !== "ok") return r;
    const hits = hitsBy.get(r.runId) ?? [];
    if (hits.length) {
      if (hits.some((h) => LEAK_PATTERNS.some((p) => h.pattern.includes(p)))) halt(`leaked answer key: transcript of ${r.runId} names ${LEAK_PATTERNS.join(", ")}`);
      return { ...r, status: "void", why: "transcript shows a forbidden path", evidence: hits.slice(0, 5) };
    }
    if (missing.has(r.runId)) return { ...r, status: "void", why: "transcript missing, so the run cannot be shown clean" };
    if (!scanned.has(r.runId)) return { ...r, status: "void", why: "transcript was not scanned" };
    return r;
  });
}

// ---------- Code grader ----------
function gradePrompt(r) {
  const cmd = fill(GRADE_CMD, { pred: `${r.out}/${FILES.labels}` });
  return [
    `You are grading one trial for SPE round ${ROUND}. Run id: ${r.runId}.`,
    `Run this one command from the repository root:`,
    "",
    cmd,
    "",
    `Report what the grader printed. For every ticket it lists, give ticketId, categoryCorrect, and priorityCorrect.`,
    `Give the grader's own summary: n, categoryAcc, and priorityAcc, as fractions from 0 to 1.`,
    `Do not edit any file. Do not re-run with other flags. Do not correct or reinterpret the grader's output.`,
    `If the grader fails, report its exit code and the last 20 lines of stderr, and leave tickets empty.`,
  ].join("\n");
}

function checkGrade(r, g) {
  if (!g) return { ok: false, why: "grade agent returned nothing" };
  if (g.exitCode !== 0) return { ok: false, why: `grader exit ${g.exitCode}. ${g.stderrTail ?? ""}`.trim() };
  const byId = new Map();
  for (const t of g.tickets) {
    if (byId.has(t.ticketId)) return { ok: false, why: `grader listed ${t.ticketId} twice` };
    byId.set(t.ticketId, t);
  }
  if (byId.size === 0) return { ok: false, why: "grader returned no ticket rows" };
  if (g.summary.n !== byId.size) return { ok: false, why: `grader summary n=${g.summary.n} but ${byId.size} ticket rows came back` };
  const rows = [...byId.values()];
  const cat = mean(rows.map((t) => (t.categoryCorrect ? 1 : 0)));
  const pri = mean(rows.map((t) => (t.priorityCorrect ? 1 : 0)));
  const tol = 0.5 / rows.length; // half a ticket, to allow for printed rounding
  const close = (a, b) => Number.isFinite(b) && Math.abs(a - b) <= tol;
  if (!close(cat, g.summary.categoryAcc) || !close(pri, g.summary.priorityAcc)) {
    return { ok: false, why: `rows give ${cat.toFixed(3)}/${pri.toFixed(3)} but the grader summary says ${g.summary.categoryAcc}/${g.summary.priorityAcc}` };
  }
  const missing = r.tickets.filter((id) => !byId.has(id));
  if (missing.length) return { ok: false, why: `grader has no row for ${missing.length} run tickets, first ${missing[0]}` };
  const grade = {};
  for (const id of r.tickets) {
    const t = byId.get(id);
    grade[id] = { categoryCorrect: t.categoryCorrect, priorityCorrect: t.priorityCorrect };
  }
  return { ok: true, grade };
}

async function gradeRun(r, ph) {
  if (state.halted) return r;
  for (let attempt = 1; attempt <= 2; attempt++) {
    if (!tryReserve(EST.agent, `grade ${r.runId} attempt ${attempt}`)) return { ...r, status: "skipped", why: "spend cap at grading" };
    const g = await callAgent(gradePrompt(r), { label: `grade-${r.runId}-a${attempt}`, phase: ph, schema: GRADE_SCHEMA });
    const check = checkGrade(r, g);
    if (check.ok) return { ...r, grade: check.grade, graderSummary: g.summary };
    log(`Grade ${r.runId} attempt ${attempt} failed: ${check.why}`);
    if (attempt === 2) {
      halt(`grader looks broken: ${r.runId}: ${check.why}`);
      return { ...r, status: "grade-failed", why: check.why };
    }
  }
  return r;
}

// ---------- Opus tone judge (only for what code cannot check) ----------
function judgePrompt(r) {
  return [
    `You are the tone judge for SPE round ${ROUND}. Run id: ${r.runId}.`,
    `Read the rubric in ${P.judge}. Read the replies in ${r.out}/${FILES.replies}. You may read ${P.tickets} for the ticket text.`,
    `Score only these tickets: ${r.tickets.join(", ")}.`,
    `For each one, give tonePass (true or false, per the rubric), a score on the rubric's scale, and a reason in one sentence.`,
    `Judge tone only. Do not judge whether the category or priority is right.`,
    `Do not open any other file. That includes ${FILES.summary}, ${FILES.labels}, ${FILES.transcript}, ${P.answers}, ${P.grader}, and anything under spe/predictions or spe/plans. Do not try to find out which config wrote the replies.`,
    `If a ticket has no reply, leave that ticket out.`,
  ].join("\n");
}

async function judgeRun(r, ph) {
  if (state.halted) return r;
  const est = EST.agent + EST.judgePerTicket * r.tickets.length;
  if (!tryReserve(est, `judge ${r.runId}`)) return { ...r, tone: {}, toneMissing: r.tickets.slice(), why: "spend cap at judging" };
  const j = await callAgent(judgePrompt(r), { label: `judge-${r.runId}`, phase: ph, schema: JUDGE_SCHEMA, model: JUDGE_MODEL });
  const want = new Set(r.tickets);
  const tone = {};
  for (const t of j ? j.tickets : []) {
    if (want.has(t.ticketId) && !(t.ticketId in tone)) tone[t.ticketId] = { tonePass: t.tonePass, score: t.score, reason: t.reason };
  }
  const toneMissing = r.tickets.filter((id) => !(id in tone));
  if (toneMissing.length) log(`Judge ${r.runId}: no tone score for ${toneMissing.length} of ${r.tickets.length} tickets.`);
  return { ...r, tone, toneMissing };
}

// ---------- One pass: trials, scan, grade, judge ----------
async function processRuns(runs, inSplit) {
  const ph = (name) => (inSplit ? "Split cells" : name);
  if (!inSplit) phase("Trials");
  let done = await parallel(runs.map((r) => () => runTrial(r, ph("Trials"))));
  if (state.halted) return done;
  if (!inSplit) phase("Peek scan");
  done = await peekScan(done, ph("Peek scan"));
  if (state.halted) return done;
  if (!inSplit) phase("Grade");
  done = await parallel(done.map((r) => () => (r.status === "ok" ? gradeRun(r, ph("Grade")) : Promise.resolve(r))));
  if (state.halted) return done;
  if (!inSplit) phase("Judge");
  done = await parallel(done.map((r) => () => (r.status === "ok" && r.grade ? judgeRun(r, ph("Judge")) : Promise.resolve(r))));
  return done;
}

// ---------- Aggregation ----------
const allRuns = [];

function cellsOf(runs, kinds) {
  const cells = new Map();
  for (const r of runs) {
    if (r.status !== "ok" || !r.grade || !kinds.includes(r.kind)) continue;
    for (const id of r.tickets) {
      const g = r.grade[id];
      if (!g) continue;
      const key = `${r.config}|${id}`;
      const c = cells.get(key) ?? { config: r.config, ticketId: id, n: 0, pass: 0, cat: 0, pri: 0, toneN: 0, tonePass: 0, toneFailReasons: [] };
      c.n += 1;
      if (g.categoryCorrect) c.cat += 1;
      if (g.priorityCorrect) c.pri += 1;
      if (g.categoryCorrect && g.priorityCorrect) c.pass += 1;
      const t = r.tone && r.tone[id];
      if (t) {
        c.toneN += 1;
        if (t.tonePass) c.tonePass += 1;
        else if (c.toneFailReasons.length < 3) c.toneFailReasons.push(`${r.runId}: ${t.reason}`);
      }
      cells.set(key, c);
    }
  }
  return cells;
}

const isSplit = (c) => c.n >= 2 && c.pass / c.n >= SPLIT_LO && c.pass / c.n <= SPLIT_HI;

// Headline uses base and top-up trials only. Extra trials over-sample split cells and would bias the means.
function summarize(runs) {
  const out = {};
  for (const cfg of CONFIGS) {
    const rs = runs.filter((r) => r.config === cfg.id && r.status === "ok" && r.grade && (r.kind === "base" || r.kind === "topup"));
    let n = 0, cat = 0, pri = 0, both = 0, toneN = 0, toneP = 0;
    const perTrial = [];
    for (const r of rs) {
      let rn = 0, rb = 0;
      for (const id of r.tickets) {
        const g = r.grade[id];
        if (!g) continue;
        n += 1;
        rn += 1;
        if (g.categoryCorrect) cat += 1;
        if (g.priorityCorrect) pri += 1;
        if (g.categoryCorrect && g.priorityCorrect) {
          both += 1;
          rb += 1;
        }
        const t = r.tone && r.tone[id];
        if (t) {
          toneN += 1;
          if (t.tonePass) toneP += 1;
        }
      }
      if (r.kind === "base" && rn) perTrial.push(rb / rn);
    }
    out[cfg.id] = {
      validRuns: rs.length,
      observations: n,
      categoryAcc: ratio(cat, n),
      priorityAcc: ratio(pri, n),
      bothAcc: ratio(both, n),
      toneRate: ratio(toneP, toneN),
      toneJudged: toneN,
      perTrialBothAcc: perTrial,
      perTrialMin: perTrial.length ? Math.min(...perTrial) : null,
      perTrialMax: perTrial.length ? Math.max(...perTrial) : null,
    };
  }
  return out;
}

function codeGaps() {
  const gaps = [];
  if (MODE === "gates") return gaps;
  const head = cellsOf(allRuns, ["base", "topup"]);
  const short = [];
  for (const cfg of CONFIGS) {
    for (const id of runTickets) {
      const n = head.get(`${cfg.id}|${id}`)?.n ?? 0;
      if (n < TRIALS) short.push(`${cfg.id}|${id} has ${n} of ${TRIALS} valid trials`);
    }
  }
  if (short.length) gaps.push(`${short.length} cells are short of ${TRIALS} valid trials. First ones: ${short.slice(0, 10).join("; ")}`);
  for (const r of allRuns) {
    if (r.status === "ok" && !r.grade) gaps.push(`${r.runId} ran but was not graded`);
    if (r.status === "ok" && r.grade && !r.tone) gaps.push(`${r.runId} was graded but not judged`);
    if (r.toneMissing && r.toneMissing.length) gaps.push(`${r.runId} has no tone score for ${r.toneMissing.length} tickets`);
  }
  if (budget.spentUsd > CAP_USD) gaps.push(`estimated spend $${r2(budget.spentUsd)} is over the $${CAP_USD} cap`);
  return gaps;
}

// ---------- Main ----------
const gates = {};

phase("Gates");
gates.inventory = await gateInventory();
if (!gates.inventory.ok) halt(`ticket inventory gate failed: ${gates.inventory.why}`);
else allTickets = gates.inventory.ids;

if (!state.halted) {
  gates.selftest = await gateSelftest();
  if (!gates.selftest.ok) halt(`grader selftest failed: ${gates.selftest.why}`);
}
if (!state.halted && (MODE === "gates" || A.rerunControl === true)) {
  gates.control = await gateControl();
  if (!gates.control.ok) {
    if (A.allowControlDiff === true) log(`Control differs and args.allowControlDiff is set. Both numbers are kept: ${gates.control.why}`);
    else halt(`regrade control failed: ${gates.control.why}`);
  }
}

if (MODE !== "gates" && !state.halted) {
  runTickets = MODE === "dry" ? allTickets.slice(0, DRY_TICKETS) : allTickets;
  const base = [];
  for (let t = 1; t <= TRIALS; t++) {
    for (const cfg of CONFIGS) base.push(makeRun(cfg, runTickets, `t${t}`, "base", t));
  }
  log(`${R} ${MODE}: ${base.length} base trials. ${CONFIGS.length} configs x ${runTickets.length} tickets = ${CONFIGS.length * runTickets.length} cells, ${TRIALS} trials per cell.`);
  allRuns.push(...(await processRuns(base, false)));

  if (MODE === "full" && !state.halted) {
    phase("Split cells");
    for (let x = 1; x <= MAX_EXTRA_ROUNDS && !state.halted; x++) {
      const head = cellsOf(allRuns, ["base", "topup"]);
      const every = cellsOf(allRuns, ["base", "topup", "extra"]);
      const planned = [];
      for (const cfg of CONFIGS) {
        const short = runTickets.filter((id) => (head.get(`${cfg.id}|${id}`)?.n ?? 0) < TRIALS);
        const split = runTickets.filter((id) => {
          const c = every.get(`${cfg.id}|${id}`);
          return c && isSplit(c);
        });
        if (short.length) planned.push(makeRun(cfg, short, `u${x}`, "topup", 1000 + x));
        if (split.length) planned.push(makeRun(cfg, split, `x${x}`, "extra", 2000 + x));
      }
      if (!planned.length) {
        log(`Extra round ${x}: no split or short cells are left.`);
        break;
      }
      log(`Extra round ${x}: ${planned.map((p) => `${p.config} ${p.kind} on ${p.tickets.length} tickets`).join(", ")}.`);
      allRuns.push(...(await processRuns(planned, true)));
    }
  }
}

// ---------- Close-out (always runs, paid from the closing reserve) ----------
const byConfig = summarize(allRuns);
const cells = [...cellsOf(allRuns, ["base", "topup", "extra"]).values()].sort((a, b) => (a.config + a.ticketId).localeCompare(b.config + b.ticketId));
const headline = CONFIGS.map((c) => `${c.id} both-correct ${pct(byConfig[c.id].bothAcc)}, tone ${pct(byConfig[c.id].toneRate)}`).join(". ");
const countBy = (s) => allRuns.filter((r) => r.status === s).length;

let analysis = null;
if (MODE !== "gates" && allRuns.some((r) => r.grade)) {
  phase("Failure analysis");
  if (tryReserve(EST.agent * 2, "failure analysis", true)) {
    const failing = cells
      .filter((c) => c.pass < c.n || c.tonePass < c.toneN)
      .map((c) => ({ config: c.config, ticketId: c.ticketId, pass: c.pass, n: c.n, categoryWrong: c.n - c.cat, priorityWrong: c.n - c.pri, toneFail: c.toneN - c.tonePass, toneFailReasons: c.toneFailReasons }));
    const folders = allRuns.filter((r) => r.grade).map((r) => ({ runId: r.runId, config: r.config, kind: r.kind, folder: r.out }));
    analysis = await callAgent(
      [
        `You are doing failure analysis for SPE round ${ROUND}. The trials are finished, so you may read the answer key now.`,
        `Headline by config (base and top-up trials only): ${JSON.stringify(byConfig)}`,
        `Cells that failed at least once: ${JSON.stringify(failing)}`,
        `Run folders: ${JSON.stringify(folders)}`,
        `Read ${P.answers}, ${P.tickets}, the run folders, and spe/failures.md.`,
        `1. Group the failures into types. Reuse an existing F-number from spe/failures.md when a type matches. Set existingId to null for a new type.`,
        `2. For each type, give the name, the kind (model, prompt, tool, harness, grader, or task), what happened, how to spot it, the run ids and tickets where it was seen, the configs, and the count.`,
        `3. List any ticket where the answer key or the grader looks wrong, with evidence. A grader bug counts as a failure.`,
        `Do not edit any file. The close-out step writes spe/failures.md later.`,
      ].join("\n"),
      { label: "failure-analysis", phase: "Failure analysis", schema: ANALYSIS_SCHEMA }
    );
  }
}

const gaps = codeGaps();
const result = {
  round: ROUND,
  roundTag: R,
  mode: MODE,
  halted: state.halted,
  haltReason: state.haltReason,
  headline,
  byConfig,
  headlineNote: "Headline numbers use base and top-up trials only. Extra trials over-sample split cells, so they appear only in the cell table.",
  gates: {
    inventory: gates.inventory ? { ok: gates.inventory.ok, count: (gates.inventory.ids ?? []).length, why: gates.inventory.why } : null,
    selftest: gates.selftest ?? null,
    control: gates.control ?? null,
  },
  budget: {
    capUsd: CAP_USD,
    estimatedSpendUsd: r2(budget.spentUsd),
    capHit: state.budgetCapHit,
    skips: budget.skips,
    basis: "Runner cost comes from summary.json when present. Agent overhead is an unmeasured per-call estimate. The counter covers this launch only.",
  },
  counts: { runs: allRuns.length, ok: countBy("ok"), void: countBy("void"), skipped: countBy("skipped"), error: countBy("error"), gradeFailed: countBy("grade-failed") },
  voids: allRuns.filter((r) => r.status === "void").map((r) => ({ runId: r.runId, config: r.config, why: r.why, evidence: r.evidence ?? null })),
  errors: allRuns.filter((r) => r.status === "error" || r.status === "grade-failed").map((r) => ({ runId: r.runId, config: r.config, why: r.why, stderrTail: r.stderrTail ?? null })),
  splitCells: cells.filter(isSplit).map((c) => ({ config: c.config, ticketId: c.ticketId, pass: c.pass, n: c.n })),
  cells,
  runs: allRuns.map((r) => ({ runId: r.runId, config: r.config, trial: r.trial, kind: r.kind, tickets: r.tickets.length, status: r.status, why: r.why ?? null, runnerCostUsd: r.runnerCostUsd ?? null, graderSummary: r.graderSummary ?? null, toneMissing: r.toneMissing ? r.toneMissing.length : null })),
  failureAnalysis: analysis,
  codeGaps: gaps,
  critic: null,
  recordedTo: null,
};

if (MODE !== "gates") {
  phase("Completeness critic");
  if (tryReserve(EST.agent, "completeness critic", true)) {
    const { cells: _omit, ...lean } = result;
    result.critic = await callAgent(
      [
        `You are the completeness critic for SPE round ${ROUND}, mode ${MODE}. Compare this result with the approved plan in spe/plans/${R}.md.`,
        `Check that every planned config ran, and that every cell has ${TRIALS} valid trials or a logged reason. Check that every void has evidence and every skip is logged with its estimate.`,
        `Check that every graded run was judged, that the grader passed its selftest, that spend stayed under $${CAP_USD}, and that every run id starts with ${R}.`,
        `Gaps found by code: ${JSON.stringify(gaps)}`,
        `Result: ${JSON.stringify(lean)}`,
        `Do not edit any file. Report each gap with a severity and a fix.`,
      ].join("\n"),
      { label: "completeness-critic", phase: "Completeness critic", schema: CRITIC_SCHEMA }
    );
  }
}

phase("Record");
const outPath = MODE === "full" ? `${P.results}/${R}.json` : `${P.results}/${R}-${MODE}.json`;
if (tryReserve(EST.agent, "record", true)) {
  const rec = await callAgent(
    [
      `Write the JSON below to ${outPath} exactly as given. Create parent folders if needed.`,
      `Do not write any other file. Do not commit. Report the path and the byte count.`,
      "",
      JSON.stringify(result, null, 2),
    ].join("\n"),
    { label: "record", phase: "Record", schema: RECORD_SCHEMA }
  );
  result.recordedTo = rec ? rec.path : null;
}

log(`${R} ${MODE} done. ${state.halted ? `Halted: ${state.haltReason}. ` : ""}${headline}. Estimated spend $${r2(budget.spentUsd)} of $${CAP_USD}.`);
return result;
